// Black-box probe harness: drives /workspace/dataset/test3_executable and parses
// its stdout/stderr so behaviour tables can be recovered without reading sources.
import { spawn } from 'node:child_process';

export const EXE = '/workspace/dataset/test3_executable';

export function run(domain, strict = '1') {
  return new Promise((resolve) => {
    const p = spawn(EXE, ['--domain', domain, '--strict', strict], {
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    const out = [];
    const err = [];
    p.stdout.on('data', (d) => out.push(d));
    p.stderr.on('data', (d) => err.push(d));
    p.on('close', (code) => {
      const stdout = Buffer.concat(out);
      const stderr = Buffer.concat(err).toString('utf8');
      // Split on \n keeping raw bytes per line, then decode as utf8.
      const lines = [];
      let start = 0;
      for (let i = 0; i < stdout.length; i++) {
        if (stdout[i] === 0x0a) {
          lines.push(stdout.subarray(start, i));
          start = i + 1;
        }
      }
      if (start < stdout.length) lines.push(stdout.subarray(start));
      resolve({ code, lines, text: lines.map((l) => l.toString('utf8')), stderr });
    });
  });
}

// Simple bounded-concurrency map.
export async function pmap(items, limit, fn) {
  const results = new Array(items.length);
  let next = 0;
  const workers = new Array(Math.min(limit, items.length)).fill(0).map(async () => {
    for (;;) {
      const i = next++;
      if (i >= items.length) return;
      results[i] = await fn(items[i], i);
    }
  });
  await Promise.all(workers);
  return results;
}

export const cps = (s) => Array.from(s).map((c) => c.codePointAt(0));
export const ch = (cp) => String.fromCodePoint(cp);
export const hex = (cp) => cp.toString(16).toUpperCase().padStart(4, '0');

