// Enumerate the codepoint universe and classify it with the Unicode properties
// Node's own regex engine exposes (categories, scripts) - no external data files.
export const RE = {
  unassigned: /\p{General_Category=Unassigned}/u,
  Lu: /\p{Lu}/u,
  Ll: /\p{Ll}/u,
  Lt: /\p{Lt}/u,
  Lm: /\p{Lm}/u,
  Lo: /\p{Lo}/u,
  Mn: /\p{Mn}/u,
  Mc: /\p{Mc}/u,
  Me: /\p{Me}/u,
  Nd: /\p{Nd}/u,
  Cc: /\p{Cc}/u,
  Cf: /\p{Cf}/u,
  Co: /\p{Co}/u,
  Cs: /\p{Cs}/u,
  Zs: /\p{Zs}/u,
  Zl: /\p{Zl}/u,
  Zp: /\p{Zp}/u,
};

const CATS = ['Lu', 'Ll', 'Lt', 'Lm', 'Lo', 'Mn', 'Mc', 'Me', 'Nd', 'Cc', 'Cf', 'Co', 'Cs', 'Zs', 'Zl', 'Zp'];

export function category(cp) {
  const c = String.fromCodePoint(cp);
  if (RE.unassigned.test(c)) return 'Cn';
  for (const k of CATS) if (RE[k].test(c)) return k;
  // Remaining: Nl No Pc Pd Ps Pe Pi Pf Po Sm Sc Sk So
  for (const k of ['Nl', 'No', 'Pc', 'Pd', 'Ps', 'Pe', 'Pi', 'Pf', 'Po', 'Sm', 'Sc', 'Sk', 'So']) {
    if (new RegExp(`\\p{${k}}`, 'u').test(c)) return k;
  }
  return 'Cn';
}

// Cached per-codepoint category (built by scanning with each regex once).
export function buildCategories() {
  const cats = new Uint8Array(0x110000);
  const names = ['Cn', ...CATS, 'Nl', 'No', 'Pc', 'Pd', 'Ps', 'Pe', 'Pi', 'Pf', 'Po', 'Sm', 'Sc', 'Sk', 'So'];
  const regexes = names.map((n) => (n === 'Cn' ? null : new RegExp(`\\p{${n}}`, 'u')));
  for (let cp = 0; cp < 0x110000; cp++) {
    if (cp >= 0xd800 && cp <= 0xdfff) { cats[cp] = names.indexOf('Cs'); continue; }
    const c = String.fromCodePoint(cp);
    let v = 0;
    for (let i = 1; i < names.length; i++) {
      if (regexes[i].test(c)) { v = i; break; }
    }
    cats[cp] = v;
  }
  return { cats, names };
}

export function isSurrogate(cp) {
  return cp >= 0xd800 && cp <= 0xdfff;
}

export function isNonCharacter(cp) {
  if ((cp & 0xfffe) === 0xfffe) return true;
  return cp >= 0xfdd0 && cp <= 0xfdef;
}

