// Approximation of Unicode's toNFKC_Casefold, built only from Node's own
// normalize()/toLowerCase() plus the documented case-folding divergences.
// Used to *guess* table entries; every guess is then verified against the
// reference executable, so imperfections here only cost extra probes.

const IGNORABLE = /\p{Default_Ignorable_Code_Point}/u;

// CaseFolding.txt entries whose C/F mapping differs from full lowercase.
const SPECIAL = new Map(Object.entries({
  'ß': 'ss',
  'µ': 'μ',
  'ſ': 's',
  'Ǆ': 'ǆ', 'ǅ': 'ǆ',
  'Ǉ': 'ǉ', 'ǈ': 'ǉ',
  'Ǌ': 'ǌ', 'ǋ': 'ǌ',
  'Ǳ': 'ǳ', 'ǲ': 'ǳ',
  'ͅ': 'ι',
  'ς': 'σ',
  'ϐ': 'β',
  'ϑ': 'θ',
  'ϕ': 'φ',
  'ϖ': 'π',
  'ϰ': 'κ',
  'ϱ': 'ρ',
  'ϵ': 'ε',
  'ẛ': 'ṡ',
  'ẞ': 'ss',
  'ι': 'ι',
  'ΐ': 'ΐ',
  'ΰ': 'ΰ',
  'İ': 'i̇',
  'ᲀ': 'в', 'ᲁ': 'д', 'ᲂ': 'о', 'ᲃ': 'с',
  'ᲄ': 'т', 'ᲅ': 'т', 'ᲆ': 'ъ', 'ᲇ': 'ѣ',
  'ᲈ': 'ꙋ',
  'ẖ': 'ẖ', 'ẗ': 'ẗ', 'ẘ': 'ẘ',
  'ẙ': 'ẙ', 'ẚ': 'aʾ',
  'ὐ': 'ὐ',
  'ὒ': 'ὒ',
  'ὔ': 'ὔ',
  'ὖ': 'ὖ',
}));

// Cherokee folds towards *uppercase* (CaseFolding.txt "T"/"C" oddity).
function cherokee(c) {
  const cp = c.codePointAt(0);
  if (cp >= 0x13f8 && cp <= 0x13fd) return String.fromCodePoint(cp - 0x8);
  if (cp >= 0xab70 && cp <= 0xabbf) return String.fromCodePoint(cp - 0x97d0);
  return null;
}

function foldOne(c) {
  const sp = SPECIAL.get(c);
  if (sp !== undefined) return sp;
  const ch = cherokee(c);
  if (ch !== null) return ch;
  const lower = c.toLowerCase();
  return lower;
}

export function casefold(s) {
  let out = '';
  for (const c of s) out += foldOne(c);
  return out;
}

export function stripIgnorable(s) {
  let out = '';
  for (const c of s) if (!IGNORABLE.test(c)) out += c;
  return out;
}

export function nfkcCf(s) {
  let x = casefold(s.normalize('NFD')).normalize('NFKC');
  // NFKC decomposition can expose further foldable content (e.g. Ⅻ -> XII).
  for (let i = 0; i < 3; i++) {
    const y = casefold(x).normalize('NFKC');
    if (y === x) break;
    x = y;
  }
  return stripIgnorable(x).normalize('NFC');
}

export const isIgnorable = (cp) => IGNORABLE.test(String.fromCodePoint(cp));

