// Generic "expect success" batch prober.
//
// The reference program encodes every label of the domain in order and reports
// only the *first* failure, so a batch whose labels are all valid costs one run
// ("Domain too long" once the joined result exceeds 253 bytes). Any error is
// attributed to the label it names; if the message carries no identity we
// bisect the batch instead.
import { run, pmap } from './probe.mjs';

const RE_CP = /Codepoint U\+([0-9A-F]{4,6})/;
const RE_FIRST = /First codepoint in label '(.*)' must be/;

// Classify stdout line 1 of the reference program.
export function firstLineVerdict(text) {
  if (text.startsWith('strict_encode_error: ')) return text.slice('strict_encode_error: '.length);
  return null; // success (bytes repr printed)
}

// Runs one domain built from `items` (array of {key, label}). Returns
// { okIndexes:Set, badIndex, message } where badIndex is the first failing item.
async function runBatch(items) {
  const domain = items.map((it) => it.label).join('.');
  const res = await run(domain, '1');
  const msg = firstLineVerdict(res.text[0] ?? '');
  if (msg === null || msg === 'Domain too long') return { ok: true, res };
  return { ok: false, msg, res };
}

function locate(items, msg) {
  let m = RE_CP.exec(msg);
  if (m) {
    const cp = parseInt(m[1], 16);
    const target = String.fromCodePoint(cp);
    for (let i = 0; i < items.length; i++) {
      if (items[i].label.includes(target)) return i;
    }
    return -1;
  }
  m = RE_FIRST.exec(msg);
  if (m) {
    for (let i = 0; i < items.length; i++) if (items[i].label === m[1]) return i;
  }
  return -1;
}

// Probe `items` expecting every one to be valid. onFail(item, msg) is called for
// each item that turns out to be invalid. Concurrency is achieved by chopping
// the list into independent chunks first.
export async function verifyAll(items, { chunk = 2500, concurrency = 24, onFail, label = '' } = {}) {
  const chunks = [];
  for (let i = 0; i < items.length; i += chunk) chunks.push(items.slice(i, i + chunk));
  let runs = 0;
  let fails = 0;
  await pmap(chunks, concurrency, async (group) => {
    let pending = group;
    while (pending.length) {
      const r = await runBatch(pending);
      runs++;
      if (r.ok) return;
      const idx = locate(pending, r.msg);
      if (idx >= 0) {
        fails++;
        onFail(pending[idx], r.msg);
        pending = pending.slice(idx + 1);
        continue;
      }
      // Unidentifiable failure: bisect.
      if (pending.length === 1) {
        fails++;
        onFail(pending[0], r.msg);
        return;
      }
      const mid = pending.length >> 1;
      const head = pending.slice(0, mid);
      const rh = await runBatch(head);
      runs++;
      if (rh.ok) {
        pending = pending.slice(mid);
      } else {
        pending = head;
      }
    }
  });
  if (label) process.stderr.write(`  ${label}: ${items.length} items, ${runs} runs, ${fails} failures\n`);
  return { runs, fails };
}

// Probe items one-by-one, returning the error message (or null on success).
export async function probeEach(items, { concurrency = 24, label = '' } = {}) {
  const out = await pmap(items, concurrency, async (it) => {
    const res = await run(it.label, '1');
    const msg = firstLineVerdict(res.text[0] ?? '');
    return { item: it, msg, res };
  });
  if (label) process.stderr.write(`  ${label}: ${items.length} individual runs\n`);
  return out;
}

