// Python-compatible value formatting.
//
// The reference implementation prints `bytes` and `str` objects with print(),
// which uses repr() for bytes and str() for strings.  Error messages built by
// the idna library also embed repr() of str labels, so repr has to match
// CPython character for character - including which codepoints CPython
// considers printable.

const NONPRINTABLE = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u;

// Codepoints assigned by the Unicode version used for the mapping tables but
// still unknown to the runtime's own character database.  CPython treats them
// as unassigned: non-printable for repr(), and without a bidirectional class.
export const UNKNOWN_TO_UCD = [[0x2ebf0, 0x2ee5d]];

export function knownToUcd(cp) {
  for (const [lo, hi] of UNKNOWN_TO_UCD) if (cp >= lo && cp <= hi) return false;
  return true;
}

// CPython's Py_UNICODE_ISPRINTABLE(): everything except the Other and
// Separator categories, with SPACE explicitly printable.
export function isPrintable(cp) {
  if (cp === 0x20) return true;
  if (!knownToUcd(cp)) return false;
  return !NONPRINTABLE.test(String.fromCodePoint(cp));
}

function hexEscape(cp) {
  if (cp <= 0xff) return '\\x' + cp.toString(16).padStart(2, '0');
  if (cp <= 0xffff) return '\\u' + cp.toString(16).padStart(4, '0');
  return '\\U' + cp.toString(16).padStart(8, '0');
}

// repr() of a Python str.
export function reprStr(s) {
  const chars = Array.from(s);
  let quote = "'";
  if (chars.includes("'") && !chars.includes('"')) quote = '"';
  let out = quote;
  for (const c of chars) {
    const cp = c.codePointAt(0);
    if (c === quote || c === '\\') out += '\\' + c;
    else if (c === '\t') out += '\\t';
    else if (c === '\n') out += '\\n';
    else if (c === '\r') out += '\\r';
    else if (cp < 0x20 || cp === 0x7f) out += hexEscape(cp);
    else if (cp < 0x7f) out += c;
    else if (!isPrintable(cp)) out += hexEscape(cp);
    else out += c;
  }
  return out + quote;
}

// repr() of a Python bytes object (accepts a Uint8Array/Buffer).
export function reprBytes(bytes) {
  const arr = Array.from(bytes);
  const hasSingle = arr.includes(0x27);
  const hasDouble = arr.includes(0x22);
  const quote = hasSingle && !hasDouble ? 0x22 : 0x27;
  let out = 'b' + String.fromCharCode(quote);
  for (const b of arr) {
    if (b === quote || b === 0x5c) out += '\\' + String.fromCharCode(b);
    else if (b === 0x09) out += '\\t';
    else if (b === 0x0a) out += '\\n';
    else if (b === 0x0d) out += '\\r';
    else if (b < 0x20 || b >= 0x7f) out += '\\x' + b.toString(16).padStart(2, '0');
    else out += String.fromCharCode(b);
  }
  return out + String.fromCharCode(quote);
}

