    else if (cp < 0x7f) out += c;
    else if (!isPrintable(cp)) out += hexEscape(cp);
    else out += c;
  }
  return out + quote;
}

// repr() of a Python bytes object (accepts a Uint8Array/Buffer).
export function reprBytes(bytes) {
  const arr = Array.from(bytes);
  const hasSingle = arr.includes(0x27);
  const hasDouble = arr.includes(0x22);
  const quote = hasSingle && !hasDouble ? 0x22 : 0x27;
  let out = 'b' + String.fromCharCode(quote);
  for (const b of arr) {
    if (b === quote || b === 0x5c) out += '\\' + String.fromCharCode(b);
    else if (b === 0x09) out += '\\t';
    else if (b === 0x0a) out += '\\n';
    else if (b === 0x0d) out += '\\r';
    else if (b < 0x20 || b >= 0x7f) out += '\\x' + b.toString(16).padStart(2, '0');
    else out += String.fromCharCode(b);
  }
  return out + String.fromCharCode(quote);
}

