// Generic "expect success" batch prober.
//
// The reference program encodes every label of the domain in order and reports
// only the *first* failure, so a batch whose labels are all valid costs a single
// run ("Domain too long" once the joined result exceeds 253 bytes).  A failure
// is attributed to the label named in the message; if the message carries no
// identity the batch is bisected instead.
import { run, pmap } from './probe.mjs';
import { reprStr } from '/output/lib/pyformat.mjs';

const RE_CP = /Codepoint U\+([0-9A-F]{4,6})/;
const RE_LABEL = / (?:in|of) label (.*?) (?:at position \d+|must be)/;
const RE_OF = / of (.*) not allowed$/;

export function firstLineVerdict(text) {
  if (text.startsWith('strict_encode_error: ')) return text.slice('strict_encode_error: '.length);
  return null; // encode() succeeded
}

async function runBatch(items) {
  const domain = items.map((it) => it.label).join('.');
  const res = await run(domain, '1');
  const msg = firstLineVerdict(res.text[0] ?? '');
  if (msg === null || msg === 'Domain too long') return { ok: true, res };
  return { ok: false, msg, res };
}

// Find which item a failure message refers to.
function locate(items, msg) {
  const mcp = RE_CP.exec(msg);
  if (mcp) {
    const target = String.fromCodePoint(parseInt(mcp[1], 16));
    for (let i = 0; i < items.length; i++) if (items[i].probe === target) return i;
    for (let i = 0; i < items.length; i++) if (items[i].label.includes(target)) return i;
    return -1;
  }
  const mlab = RE_LABEL.exec(msg) || RE_OF.exec(msg);
  if (mlab) {
    for (let i = 0; i < items.length; i++) if (reprStr(items[i].label) === mlab[1]) return i;
  }
  return -1;
}

async function processGroup(items, onFail, onOk, stats) {
  let pending = items;
  while (pending.length) {
    const r = await runBatch(pending);
    stats.runs++;
    if (r.ok) {
      for (const it of pending) onOk(it);
      return;
    }
    const idx = locate(pending, r.msg);
    if (idx >= 0) {
      for (let i = 0; i < idx; i++) onOk(pending[i]);
      stats.fails++;
      onFail(pending[idx], r.msg, r.res);
      pending = pending.slice(idx + 1);
      continue;
    }
    if (pending.length === 1) {
      stats.fails++;
      onFail(pending[0], r.msg, r.res);
      return;
    }
    const mid = pending.length >> 1;
    await processGroup(pending.slice(0, mid), onFail, onOk, stats);
    pending = pending.slice(mid);
  }
}

// items: [{key, label, probe}] - `probe` is the codepoint character under test.
export async function verifyAll(items, { chunk = 2000, concurrency = 24, onFail, onOk, label = '' } = {}) {
  for (const it of items) {
    if (it.label.includes('.')) throw new Error(`label with dot: ${JSON.stringify(it.label)}`);
  }
  const chunks = [];
  for (let i = 0; i < items.length; i += chunk) chunks.push(items.slice(i, i + chunk));
  const stats = { runs: 0, fails: 0 };
  await pmap(chunks, concurrency, (group) => processGroup(group, onFail, onOk, stats));
  if (label) process.stderr.write(`  ${label}: ${items.length} items, ${stats.runs} runs, ${stats.fails} failures\n`);
  return stats;
}

export async function probeEach(items, { concurrency = 24, label = '' } = {}) {
  const out = await pmap(items, concurrency, async (it) => {
    const res = await run(it.label, '1');
    return { item: it, msg: firstLineVerdict(res.text[0] ?? ''), res };
  });
  if (label) process.stderr.write(`  ${label}: ${items.length} individual runs\n`);
  return out;
}

