// each item that turns out to be invalid. Concurrency is achieved by chopping
// the list into independent chunks first.
export async function verifyAll(items, { chunk = 2500, concurrency = 24, onFail, label = '' } = {}) {
  const chunks = [];
  for (let i = 0; i < items.length; i += chunk) chunks.push(items.slice(i, i + chunk));
  let runs = 0;
  let fails = 0;
  await pmap(chunks, concurrency, async (group) => {
    let pending = group;
    while (pending.length) {
      const r = await runBatch(pending);
      runs++;
      if (r.ok) return;
