// Recovers the IDNA2008 codepoint classes (PVALID / CONTEXTJ / CONTEXTO /
// DISALLOWED) from the reference executable's observable behaviour.
import fs from 'node:fs';
import { buildCategories } from './candidates.mjs';
import { nfkcCf } from './nfkccf.mjs';
import { verifyAll, probeEach } from './batch.mjs';

const CACHE = '/workspace/build/cache';
fs.mkdirSync(CACHE, { recursive: true });
const ch = (cp) => String.fromCodePoint(cp);

// RFC 5892 exception table; each entry is verified by a targeted probe elsewhere.
export const CONTEXTJ = [[0x200c, 0x200d]];
export const CONTEXTO = [
  [0x00b7, 0x00b7], [0x0375, 0x0375], [0x05f3, 0x05f4],
  [0x0660, 0x0669], [0x06f0, 0x06f9], [0x30fb, 0x30fb],
];
const CONTEXT_CPS = new Set();
for (const [a, b] of [...CONTEXTJ, ...CONTEXTO]) for (let cp = a; cp <= b; cp++) CONTEXT_CPS.add(cp);

// RFC 5892 "LDH" rule - the only PVALID ASCII codepoints.
const ASCII_PVALID = [0x2d, ...Array.from({ length: 10 }, (_, i) => 0x30 + i),
  ...Array.from({ length: 26 }, (_, i) => 0x61 + i)];

const LETTER_DIGITS = new Set(['Ll', 'Lu', 'Lt', 'Lm', 'Lo', 'Mn', 'Mc', 'Nd']);
const MARKS = new Set(['Mn', 'Mc', 'Me']);
const RE_INVALID_CP = /^Codepoint U\+[0-9A-F]{4,6} at position \d+ of .* not allowed$/;

const { cats, names } = buildCategories();
const cat = (cp) => names[cats[cp]];

const candidates = [];
for (let cp = 0x80; cp < 0x110000; cp++) {
  if (cp >= 0xd800 && cp <= 0xdfff) continue;
  if (CONTEXT_CPS.has(cp)) continue;
  if (LETTER_DIGITS.has(cat(cp)) || MARKS.has(cat(cp))) candidates.push(cp);
}

const disallowed = new Set();
const pvalid = new Set(ASCII_PVALID);
const oddities = [];
const probe = [];
for (const cp of candidates) {
  const c = ch(cp);
  if (cp >= 0x80 && cp <= 0x9f) { disallowed.add(cp); continue; } // C1, cannot ride argv
  if (c.normalize('NFC') !== c) { disallowed.add(cp); continue; } // never NFKC_CF-stable
  probe.push(cp);
}

const labelFor = (cp) => (MARKS.has(cat(cp)) ? '例' + ch(cp) : ch(cp));
const mk = (cp) => ({ key: cp, label: labelFor(cp), probe: ch(cp) });

const groupA = [];
const groupB = [];
for (const cp of probe) (nfkcCf(ch(cp)) === ch(cp) ? groupA : groupB).push(mk(cp));
process.stderr.write(`candidates=${candidates.length} guessPVALID=${groupA.length} guessDISALLOWED=${groupB.length}\n`);

await verifyAll(groupA, {
  label: 'pvalid-guess',
  onOk: (item) => pvalid.add(item.key),
  onFail: (item, msg) => {
    if (RE_INVALID_CP.test(msg)) disallowed.add(item.key);
    else { pvalid.add(item.key); oddities.push([item.key, msg]); }
  },
});

const results = await probeEach(groupB, { label: 'disallowed-guess' });
for (const r of results) {
  if (r.msg !== null && RE_INVALID_CP.test(r.msg)) disallowed.add(r.item.key);
  else { pvalid.add(r.item.key); oddities.push([r.item.key, r.msg]); }
}

// Cross-check: ASCII PVALID assumption, plus a sample of non-LetterDigits.
const checks = [
  { key: -1, label: '例abc-123xyz', probe: 'q' },
  { key: -2, label: '例A', probe: 'A' },
  { key: -3, label: '例_', probe: '_' },
];
const cres = await probeEach(checks, { label: 'ascii-crosscheck' });
for (const r of cres) process.stderr.write(`    ${JSON.stringify(r.item.label)} -> ${r.msg}\n`);

const sample = [];
for (let cp = 0xa0; cp < 0x110000; cp += 397) {
  if (cp >= 0xd800 && cp <= 0xdfff) continue;
  if (CONTEXT_CPS.has(cp)) continue;
  const c = cat(cp);
  if (LETTER_DIGITS.has(c) || MARKS.has(c) || c === 'Cn') continue;
  sample.push(mk(cp));
}
const sres = await probeEach(sample, { label: 'non-letterdigit-sample' });
const surprises = sres.filter((r) => r.msg === null || !RE_INVALID_CP.test(r.msg));
process.stderr.write(`  sample=${sample.length} unexpectedly-valid=${surprises.length}\n`);
for (const s of surprises.slice(0, 20)) {
  process.stderr.write(`    U+${s.item.key.toString(16).toUpperCase()} (${cat(s.item.key)}) -> ${s.msg}\n`);
}

fs.writeFileSync(`${CACHE}/pvalid.json`, JSON.stringify({
  pvalid: [...pvalid].sort((a, b) => a - b),
  oddities: oddities.map(([cp, m]) => [cp.toString(16), m]),
  surprises: surprises.map((s) => [s.item.key.toString(16), s.msg]),
}));
process.stderr.write(`PVALID codepoints: ${pvalid.size}, DISALLOWED probed: ${disallowed.size}\n`);

