  [0x00b7, 0x00b7], [0x0375, 0x0375], [0x05f3, 0x05f4],
  [0x0660, 0x0669], [0x06f0, 0x06f9], [0x30fb, 0x30fb],
];
const CONTEXT_CPS = new Set();
for (const [a, b] of [...CONTEXTJ, ...CONTEXTO]) for (let cp = a; cp <= b; cp++) CONTEXT_CPS.add(cp);

const LETTER_DIGITS = new Set(['Ll', 'Lu', 'Lt', 'Lm', 'Lo', 'Mn', 'Mc', 'Nd']);
const MARKS = new Set(['Mn', 'Mc', 'Me']);

const RE_INVALID_CP = /^Codepoint U\+[0-9A-F]{4,6} at position \d+ of .* not allowed$/;

function main() {
  const { cats, names } = buildCategories();
  const cat = (cp) => names[cats[cp]];

  const candidates = [];
  for (let cp = 0; cp < 0x110000; cp++) {
    if (cp >= 0xd800 && cp <= 0xdfff) continue;
    if (CONTEXT_CPS.has(cp)) continue;
    const c = cat(cp);
