  // Non-NFC codepoints can never be PVALID (they are NFKC_CF-unstable).
  // C0/C1 controls cannot travel through argv at all, and are never PVALID.
  const disallowed = new Set();
  const pvalid = new Set();
  const probe = [];
  for (const cp of candidates) {
    const c = ch(cp);
    if (cp < 0x20 || cp === 0x7f || (cp >= 0x80 && cp <= 0x9f)) { disallowed.add(cp); continue; }
    if (c.normalize('NFC') !== c) { disallowed.add(cp); continue; }
    probe.push(cp);
  }

  const labelFor = (cp) => (MARKS.has(cat(cp)) || cp < 0x80 ? '例' + ch(cp) : ch(cp));

  const groupA = []; // guessed PVALID  -> expect batch success
  const groupB = []; // guessed DISALLOWED -> individual probe
  for (const cp of probe) {
    const c = ch(cp);
    (nfkcCf(c) === c ? groupA : groupB).push({ key: cp, label: labelFor(cp) });
  }
  process.stderr.write(`candidates=${candidates.length} nonNFC=${disallowed.size} guessPVALID=${groupA.length} guessDISALLOWED=${groupB.length}\n`);

  const oddities = [];
  return (async () => {
    await verifyAll(groupA, {
      label: 'pvalid-guess',
      onFail: (item, msg) => {
        if (RE_INVALID_CP.test(msg)) disallowed.add(item.key);
        else { pvalid.add(item.key); oddities.push([item.key, msg]); }
      },
    });
    for (const it of groupA) if (!disallowed.has(it.key)) pvalid.add(it.key);

    const results = await probeEach(groupB, { label: 'disallowed-guess' });
    for (const r of results) {
      if (r.msg !== null && RE_INVALID_CP.test(r.msg)) disallowed.add(r.item.key);
      else { pvalid.add(r.item.key); oddities.push([r.item.key, r.msg]); }
    }

    // Sanity sample: codepoints outside LetterDigits must be DISALLOWED.
    const sample = [];
    for (let cp = 0xa0; cp < 0x110000; cp += 397) {
      if (cp >= 0xd800 && cp <= 0xdfff) continue;
      if (CONTEXT_CPS.has(cp)) continue;
      const c = cat(cp);
      if (LETTER_DIGITS.has(c) || MARKS.has(c) || c === 'Cn') continue;
      sample.push({ key: cp, label: labelFor(cp) });
    }
    const sres = await probeEach(sample, { label: 'non-letterdigit-sample' });
    const surprises = sres.filter((r) => r.msg === null || !RE_INVALID_CP.test(r.msg));
    process.stderr.write(`  sample=${sample.length} unexpectedly-valid=${surprises.length}\n`);
    for (const s of surprises.slice(0, 20)) {
      process.stderr.write(`    U+${s.item.key.toString(16).toUpperCase()} (${cat(s.item.key)}) -> ${s.msg}\n`);
    }

    fs.writeFileSync(`${CACHE}/pvalid.json`, JSON.stringify({
      pvalid: [...pvalid].sort((a, b) => a - b),
      oddities: oddities.map(([cp, m]) => [cp.toString(16), m]).slice(0, 400),
      surprises: surprises.map((s) => [s.item.key.toString(16), s.msg]),
    }));
    process.stderr.write(`PVALID codepoints: ${pvalid.size}\n`);
  })();
}

await main();

