// Second PVALID pass: every remaining assigned codepoint outside the
// LetterDigits categories is probed individually, so RFC 5892 "Exceptions" and
// "BackwardCompatible" entries are discovered rather than assumed.
import fs from 'node:fs';
import { buildCategories } from './candidates.mjs';
import { probeEach } from './batch.mjs';

const CACHE = '/workspace/build/cache';
const ch = (cp) => String.fromCodePoint(cp);
const { cats, names } = buildCategories();
const cat = (cp) => names[cats[cp]];

const data = JSON.parse(fs.readFileSync(`${CACHE}/pvalid.json`, 'utf8'));
const known = new Set(data.pvalid);
const LETTER_DIGITS = new Set(['Ll', 'Lu', 'Lt', 'Lm', 'Lo', 'Mn', 'Mc', 'Me', 'Nd']);
const RE_INVALID_CP = /^Codepoint U\+[0-9A-F]{4,6} at position \d+ of .* not allowed$/;

const todo = [];
for (let cp = 0xa0; cp < 0x110000; cp++) {
  if (cp >= 0xd800 && cp <= 0xdfff) continue;
  const c = cat(cp);
  if (c === 'Cn' || c === 'Co' || c === 'Cs' || c === 'Cc') continue;
  if (LETTER_DIGITS.has(c)) continue;
  todo.push({ key: cp, label: '例' + ch(cp), probe: ch(cp) });
}
// Private use / a few unassigned spot checks.
for (const cp of [0xe000, 0xf8ff, 0xf0000, 0x10fffd, 0x2a6e0, 0x0378]) {
  todo.push({ key: cp, label: '例' + ch(cp), probe: ch(cp) });
}
process.stderr.write(`non-letterdigit codepoints to probe: ${todo.length}\n`);

const res = await probeEach(todo, { label: 'exceptions', concurrency: 28 });
const found = [];
for (const r of res) {
  if (r.msg === null || !RE_INVALID_CP.test(r.msg)) found.push([r.item.key, r.msg]);
}
process.stderr.write(`not plainly DISALLOWED: ${found.length}\n`);
for (const [cp, msg] of found) {
  process.stderr.write(`  U+${cp.toString(16).toUpperCase().padStart(4, '0')} (${cat(cp)}) -> ${msg}\n`);
}
fs.writeFileSync(`${CACHE}/exceptions.json`, JSON.stringify(found.map(([cp, m]) => [cp.toString(16), m])));

