// Recovers the UTS-46 mapping table (as exercised by uts46_remap with its
// default arguments) from the reference executable.
//
// Trick: the program prints the remapped domain on stdout line 2, so a domain
// built from many single-codepoint segments joined by '.' yields the mapping of
// every segment in one run.  A codepoint that is disallowed aborts the program,
// but names itself on stderr, so the batch can resume just past it.
import fs from 'node:fs';
import { buildCategories } from './candidates.mjs';
import { run, pmap } from './probe.mjs';

const CACHE = '/workspace/build/cache';
fs.mkdirSync(CACHE, { recursive: true });
const ch = (cp) => String.fromCodePoint(cp);
const { cats, names } = buildCategories();
const cat = (cp) => names[cats[cp]];

const RE_DISALLOWED = /Codepoint U\+([0-9A-F]{4,6}) not allowed at position (\d+) in/;

const mapping = new Map(); // cp -> string ('' means ignored)
const disallowed = new Set();
const unresolved = [];

async function probeGroup(cpList) {
  let pending = cpList;
  let runs = 0;
  while (pending.length) {
    const domain = pending.map(ch).join('.');
    const res = await run(domain, '1');
    runs++;
    if (res.text.length >= 2 && res.code === 0) {
      const segs = res.text[1].split('.');
      if (segs.length === pending.length) {
        for (let i = 0; i < pending.length; i++) mapping.set(pending[i], segs[i]);
        return runs;
      }
      // A replacement contained a '.' (or a newline): split and retry.
      if (pending.length === 1) { unresolved.push([pending[0], res.text.slice(1).join('\n')]); return runs; }
      const mid = pending.length >> 1;
      runs += await probeGroup(pending.slice(0, mid));
      pending = pending.slice(mid);
      continue;
    }
    const m = RE_DISALLOWED.exec(res.stderr);
    if (m) {
      const cp = parseInt(m[1], 16);
      const idx = pending.indexOf(cp);
      if (idx < 0) { unresolved.push([pending[0], `stderr names U+${m[1]} not in batch`]); return runs; }
      disallowed.add(cp);
      // Everything before it in this batch is unknown still - re-probe.
      if (idx > 0) runs += await probeGroup(pending.slice(0, idx));
      pending = pending.slice(idx + 1);
      continue;
    }
    if (pending.length === 1) { unresolved.push([pending[0], `code=${res.code} stderr=${res.stderr.slice(-200)}`]); return runs; }
    const mid = pending.length >> 1;
    runs += await probeGroup(pending.slice(0, mid));
    pending = pending.slice(mid);
  }
  return runs;
}

// Everything assigned except: ASCII (hardcoded), surrogates, private use and
// unassigned (spot-checked), and codepoints that cannot travel through argv.
const candidates = [];
for (let cp = 0x80; cp < 0x110000; cp++) {
  if (cp >= 0xd800 && cp <= 0xdfff) continue;
  const c = cat(cp);
  if (c === 'Cn' || c === 'Co') continue;
  candidates.push(cp);
}
// Spot checks for the ranges we intend to hardcode as disallowed.
const spot = [];
for (let cp = 0xe000; cp <= 0xf8ff; cp += 617) spot.push(cp);
for (let cp = 0xf0000; cp <= 0x10fffd; cp += 9973) spot.push(cp);
for (let cp = 0x378; cp < 0x110000; cp += 4093) if (cat(cp) === 'Cn' && !(cp >= 0xd800 && cp <= 0xdfff)) spot.push(cp);
for (const cp of [0xfdd0, 0xfffe, 0xffff, 0x1fffe, 0x10fffe]) spot.push(cp);

process.stderr.write(`uts46 candidates=${candidates.length} spot=${spot.length}\n`);

const CHUNK = 1200;
const chunks = [];
for (let i = 0; i < candidates.length; i += CHUNK) chunks.push(candidates.slice(i, i + CHUNK));
for (let i = 0; i < spot.length; i += 200) chunks.push(spot.slice(i, i + 200));

let totalRuns = 0;
let done = 0;
await pmap(chunks, 24, async (group) => {
  totalRuns += await probeGroup(group);
  done++;
  if (done % 20 === 0) process.stderr.write(`  ..${done}/${chunks.length} chunks, ${totalRuns} runs\n`);
});

process.stderr.write(`mapped=${mapping.size} disallowed=${disallowed.size} unresolved=${unresolved.length} runs=${totalRuns}\n`);
for (const [cp, why] of unresolved.slice(0, 30)) {
  process.stderr.write(`  U+${cp.toString(16).toUpperCase()} unresolved: ${JSON.stringify(why).slice(0, 160)}\n`);
}

fs.writeFileSync(`${CACHE}/uts46.json`, JSON.stringify({
  mapping: [...mapping].map(([cp, v]) => [cp, v]),
  disallowed: [...disallowed].sort((a, b) => a - b),
  unresolved,
}));

